/**
 * Server-side airport directory + flight assistance pricing boundary.
 *
 * Airport data: the OurAirports public-domain dataset, loaded into the
 * `airports` table (supabase/seed/airports.sql, generated by
 * scripts/load-airports.mjs). Autocomplete searches that table — no hardcoded
 * city lists remain anywhere.
 *
 * Fares: live provider quotes come only from the configured Amadeus
 * credentials via src/lib/flights.ts. When unconfigured, the UI shows an
 * honest unavailable state and offers a booking-assistance request — no
 * invented fares, schedules, or availability, ever.
 */
import { createClient, isSupabaseConfigured } from "./supabase/server";
import { haversineKm } from "./geo";
import { lineTotal as lineTotalPure, orderTotal as orderTotalPure, type OrderLine } from "./pricing";

// Re-export the pure pricing helpers for callers that already import this
// module (they live in the dependency-free pricing module for testability).
export function lineTotal(line: OrderLine): number {
  return lineTotalPure(line);
}
export function orderTotal(lines: OrderLine[]): { total: number; currency: string | null } {
  return orderTotalPure(lines);
}

export interface AirportRow {
  id: string;
  ident: string;
  iata_code: string | null;
  icao_code: string | null;
  name: string;
  city_municipality: string | null;
  iso_country: string; // char(2)
  latitude: number;
  longitude: number;
  airport_type: string;
  active: boolean;
}

export type AirportSuggestion = Pick<
  AirportRow,
  "id" | "name" | "city_municipality" | "iata_code" | "icao_code" | "iso_country" | "airport_type"
> & { latitude: number; longitude: number };

/** Autocomplete: searches IATA, ICAO, name, and city; active rows only. */
export async function searchAirports(
  query: string,
  limit = 8,
): Promise<AirportSuggestion[]> {
  const q = query.trim();
  if (q.length < 2) return [];
  if (!isSupabaseConfigured()) return [];

  const supabase = createClient();
  const like = `%${q}%`;
  const { data } = await supabase
    .from("airports")
    .select(
      "id, name, city_municipality, iata_code, icao_code, iso_country, airport_type, latitude, longitude",
    )
    .eq("active", true)
    .or(
      [
        `iata_code.ilike.${q}%`,
        `or(icao_code.ilike.${q}%,name.ilike.${like}%,city_municipality.ilike.${like}%)`,
      ].join(","),
    )
    .order("airport_type", { ascending: true })
    .limit(limit);

  return (data ?? []) as unknown as AirportSuggestion[];
}

/** Batch-resolve airport rows for order/trip summaries. */
export async function getAirportsByIds(ids: string[]): Promise<AirportRow[]> {
  if (ids.length === 0 || !isSupabaseConfigured()) return [];
  const supabase = createClient();
  const { data } = await supabase
    .from("airports")
    .select("*")
    .in("id", ids);
  return (data ?? []) as unknown as AirportRow[];
}

/**
 * Approximate geographic (great-circle) distance between two airports from
 * their verified dataset coordinates. ALWAYS labelled as approximate
 * geographic distance — never as actual flight-path or flown distance, and
 * never used to invent a fare or flight time.
 */
export function airportDistanceKm(a: AirportRow, b: AirportRow): number {
  return haversineKm(a.latitude, a.longitude, b.latitude, b.longitude);
}

// ---------------------------------------------------------------------------
// Flight assistance service pricing — server-side only
// ---------------------------------------------------------------------------

/**
 * The only purchasable flight-related service today is the booking-assistance
 * fee. The airline fare itself is NEVER a VisaBridge charge: when live fare
 * search is configured, the customer pays the provider's fare separately and
 * our fee covers the assistance; when it is not configured, the customer
 * submits a request and a human confirms real availability before any money
 * for a ticket changes hands. The service fee is always the
 * administrator-controlled `flight_ticketing` service_fees row.
 */
export const FLIGHT_SERVICE_KEY = "flight_ticketing";

export interface FlightFeeLine {
  lineKey: string;
  labelEn: string;
  labelBn: string;
  kind: "agency_service";
  unitAmount: number;
  quantity: number;
  currency: string;
  priceSource: string;
}

/** Reads the active administrator-controlled fee for flight assistance. */
export async function getFlightServiceFee(): Promise<FlightFeeLine | null> {
  if (!isSupabaseConfigured()) return null;
  const supabase = createClient();
  const { data } = await supabase
    .from("service_fees")
    .select("key, label_en, label_bn, amount, currency, active")
    .eq("key", FLIGHT_SERVICE_KEY)
    .eq("active", true)
    .maybeSingle();
  if (!data) return null;
  return {
    lineKey: "flight_assistance",
    labelEn: data.label_en,
    labelBn: data.label_bn ?? data.label_en,
    kind: "agency_service",
    unitAmount: Number(data.amount),
    quantity: 1,
    currency: data.currency,
    priceSource: `service_fees:${data.key}@${new Date().toISOString()}`,
  };
}
